**C++**

```cpp
#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; i++){
        cin >> a[i];
    }
    for (int i = 0; i < n; i++){
        cin >> b[i];
    }

    long long S = 0, S_a = 0, S_b = 0;
    // 注意下标转换：题中下标从1开始，因此对于数组下标 i（0-indexed）对应权值为 (i+1)*(n-i)
    for (int i = 0; i < n; i++){
        long long weight = (long long)(i+1) * (n - i) % MOD;
        S = (S + weight) % MOD;
        if(a[i] == 1)
            S_a = (S_a + weight) % MOD;
        if(b[i] == 1)
            S_b = (S_b + weight) % MOD;
    }

    long long ans = (S * ((S_a + S_b) % MOD) % MOD - 2LL * S_a % MOD * S_b % MOD) % MOD;
    if(ans < 0) ans += MOD;
    cout << ans << "\n";
    return 0;
}
```

