import sys

MOD = 1000000007

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    P = list(map(int, data[1:1+n]))
    Q = list(map(int, data[1+n:1+2*n]))

    S = 0
    SP = 0
    SQ = 0

    for i in range(n):
        # 下标从0开始，对应原题中的 i+1，权值为 (i+1)*(n-i)
        weight = (i + 1) * (n - i) % MOD
        S = (S + weight) % MOD
        if P[i] == 1:
            SP = (SP + weight) % MOD
        if Q[i] == 1:
            SQ = (SQ + weight) % MOD

    ans = (S * ((SP + SQ) % MOD) % MOD - 2 * SP % MOD * SQ % MOD) % MOD
    if ans < 0:
        ans += MOD

    print(ans)

if __name__ == "__main__":
    main()
```

